import en from "../locales/en/index.json";
import fr from "../locales/fr/index.json";

const locales = {
  en,
  fr,
} as const;

type SupportedLanguage = keyof typeof locales;

function getDictionary(language?: string) {
  return locales[(language as SupportedLanguage) === "en" ? "en" : "fr"];
}

export function getLocaleValue<T>(language: string | undefined, key: string): T | undefined {
  const dictionary = getDictionary(language) as Record<string, unknown>;

  return key.split(".").reduce<unknown>((current, segment) => {
    if (!current || typeof current !== "object") {
      return undefined;
    }

    return (current as Record<string, unknown>)[segment];
  }, dictionary) as T | undefined;
}
