import * as React from "react";
import { useLocation } from "@reach/router";
import {
  isAnalyticsStarted,
  getStoredConsent,
  initForGrantedConsent,
  trackPageView,
} from "../utils/analytics";

export default function AnalyticsBootstrap() {
  const location = useLocation();
  const currentPath = `${location.pathname}${location.search}${location.hash}`;
  const latestPathRef = React.useRef(currentPath);

  // Track page views on client-side navigation (only when analytics is already running)
  React.useEffect(() => {
    latestPathRef.current = currentPath;
    if (isAnalyticsStarted()) {
      trackPageView(currentPath);
    }
  }, [currentPath]);

  // On mount: load analytics for returning users who previously granted consent.
  // !isAnalyticsStarted() prevents this from double-firing when Gatsby remounts
  // Layout across navigations (the [currentPath] effect above handles those).
  React.useEffect(() => {
    if (typeof window === "undefined") return;
    if (getStoredConsent() === "granted" && !isAnalyticsStarted()) {
      void initForGrantedConsent().then(() => {
        trackPageView(latestPathRef.current);
      });
    }
  }, []);

  return null;
}
